/*
 * A353090  Column -2 of the extended Trithoff (tribonacci) array.
 * https://oeis.org/A353090
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = min{ k ≥ 0 : Σ_{i=0}^{k} m(i) ≥ n }, with m(0) = 2, and
 *            for i > 0, m(i) = 2 if i is a position of the letter 'c' in the
 *            Tribonacci word (A003146), otherwise m(i) = 3. (The Tribonacci
 *            word is generated by the morphism a → ab, b → ac, c → a,
 *            starting from "a".)
 * Range:     u8 n <= 77, u16 n <= 77, u32 n <= 77, u64 n <= 77, u128 n <= 77,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <string.h>

static size_t word_len = 0;          /* length of the Tribonacci word built */
static uint8_t *c_positions = NULL;  /* 1 if position holds 'c', 0 otherwise */

/* Build the Tribonacci word long enough to cover the required positions.
   The length 200000 comfortably covers the needs for all n up to at least
   1e6 terms of this sequence. */
static void build_tribonacci_word(void)
{
    const size_t TARGET = 200000;      /* desired word length */
    size_t cur_len = 1;
    char *cur = (char *)malloc(cur_len);
    cur[0] = 'a';

    size_t next_len;
    while (cur_len < TARGET) {
        /* At most twice as long as the current word + 1 */
        next_len = cur_len * 2 + 1;
        char *next = (char *)malloc(next_len);
        size_t pos = 0;
        for (size_t i = 0; i < cur_len; ++i) {
            char ch = cur[i];
            if (ch == 'a') {
                next[pos++] = 'a';
                next[pos++] = 'b';
            } else if (ch == 'b') {
                next[pos++] = 'a';
                next[pos++] = 'c';
            } else { /* ch == 'c' */
                next[pos++] = 'a';
            }
        }
        free(cur);
        cur = next;
        cur_len = pos;
    }

    word_len = cur_len;
    c_positions = (uint8_t *)calloc(word_len + 1, sizeof(uint8_t));
    for (size_t i = 1; i <= word_len; ++i) {
        if (cur[i - 1] == 'c')
            c_positions[i] = 1;
    }
    free(cur);
}

/* Main sequence function. */
seq_t a(idx_t n)
{
    /* n is ≥ 1 by problem statement. */
    if (c_positions == NULL)
        build_tribonacci_word();

    idx_t count = 0;            /* cumulative number of terms produced so far */

    for (idx_t k = 0;; ++k) {
        idx_t mult;              /* multiplicity of integer k */

        if (k == 0)
            mult = 2;
        else if (k <= word_len && c_positions[(size_t)k])
            mult = 2;
        else
            mult = 3;

        if (count + mult >= n)
            return (seq_t)k;

        count += mult;
    }
}
